"""Provenance records attached to every acquired product and every derived result.

A record states where something came from and how it was obtained. Required
fields are enforced at construction so incomplete provenance cannot be
created silently.
"""

from __future__ import annotations

import hashlib
import json
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from typing import Any

# How the bytes reached us. "fixture" means committed demo/test data;
# "synthetic" means generated by code and never an observation.
DATA_ORIGINS = ("live", "cache", "fixture", "synthetic")


class ProvenanceError(ValueError):
    """Raised when a provenance record is incomplete or inconsistent."""


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def stable_hash(obj: Any) -> str:
    """Hash of a JSON-serialisable object, independent of key order."""
    blob = json.dumps(obj, sort_keys=True, separators=(",", ":"), default=str)
    return hashlib.sha256(blob.encode()).hexdigest()


@dataclass(frozen=True)
class Provenance:
    source: str                 # e.g. "IRSA", "SIMBAD", "Gaia Archive", "skytrace"
    source_url: str             # exact URL requested, or "" for derived results
    retrieved_at: str           # ISO-8601 UTC time of the original retrieval
    origin: str                 # one of DATA_ORIGINS
    dataset_id: str = ""        # e.g. DOI or collection name
    release: str = ""           # e.g. "QR3"
    content_sha256: str = ""    # hash of the stored bytes, if any
    processing: tuple[str, ...] = field(default_factory=tuple)  # ordered steps applied
    notes: str = ""

    def __post_init__(self) -> None:
        if self.origin not in DATA_ORIGINS:
            raise ProvenanceError(f"origin must be one of {DATA_ORIGINS}, got {self.origin!r}")
        if not self.source:
            raise ProvenanceError("source is required")
        if not self.retrieved_at:
            raise ProvenanceError("retrieved_at is required")
        if self.origin in ("live", "cache") and not self.source_url:
            raise ProvenanceError("archive data must record its source_url")
        if self.origin == "synthetic" and self.source != "synthetic":
            raise ProvenanceError("synthetic data must use source='synthetic'")

    def with_origin(self, origin: str) -> "Provenance":
        """Same record, re-labelled when served from cache or a fixture.

        retrieved_at keeps the time of the original live retrieval, so a cached
        response is never presented as current.
        """
        d = asdict(self)
        d["origin"] = origin
        return Provenance(**d)

    def with_step(self, step: str) -> "Provenance":
        d = asdict(self)
        d["processing"] = tuple(self.processing) + (step,)
        return Provenance(**d)

    def to_dict(self) -> dict[str, Any]:
        d = asdict(self)
        d["processing"] = list(self.processing)
        return d

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Provenance":
        d = dict(d)
        d["processing"] = tuple(d.get("processing", ()))
        return cls(**d)


def synthetic(notes: str) -> Provenance:
    """Provenance for generated test data. It can never pass as an observation."""
    return Provenance(source="synthetic", source_url="", retrieved_at=utc_now_iso(),
                      origin="synthetic", notes=notes)
